1	// Package store keeps the API's data in memory. It is safe for concurrent use.
2	package store
3	
4	import (
5		"errors"
6		"fmt"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// Plan is an account's or a customer's subscription plan.
14	type Plan string
15	
16	const (
17		PlanFree Plan = "free"
18		PlanPro  Plan = "pro"
19	)
20	
21	// Valid reports whether p is a known plan.
22	func (p Plan) Valid() bool { return p == PlanFree || p == PlanPro }
23	
24	// Account is one tenant of the product.
25	type Account struct {
26		ID   string
27		Name string
28		Plan Plan
29		// TaxRateBP is the tax rate charged on this account's invoices, in basis points (1% = 100).
30		TaxRateBP int
31	}
32	
33	// Customer is one of an account's customers.
34	type Customer struct {
35		ID        string    `json:"id"`
36		AccountID string    `json:"-"`
37		Name      string    `json:"name"`
38		Email     string    `json:"email"`
39		Plan      Plan      `json:"plan"`
40		CreatedAt time.Time `json:"created_at"`
41	}
42	
43	// LineItem is one line of an invoice.
44	type LineItem struct {
45		Description string `json:"description"`
46		Quantity    int    `json:"quantity"`
47		UnitCents   int64  `json:"unit_cents"`
48	}
49	
50	// Invoice is a bill to a customer.
51	type Invoice struct {
52		ID         string     `json:"id"`
53		AccountID  string     `json:"-"`
54		CustomerID string     `json:"customer_id"`
55		Lines      []LineItem `json:"lines"`
56		// CouponPercent is a percentage discount (0 to 100).
57		CouponPercent int `json:"coupon_percent"`
58		// CreditCents is a fixed amount taken off the invoice.
59		CreditCents int64     `json:"credit_cents"`
60		TaxRateBP   int       `json:"tax_rate_bp"`
61		CreatedAt   time.Time `json:"created_at"`
62	}
63	
64	// Errors.
65	var (
66		ErrNotFound = errors.New("not found")
67		ErrInvalid  = errors.New("invalid")
68	)
69	
70	// Store holds everything.
71	type Store struct {
72		mu        sync.Mutex
73		accounts  map[string]Account
74		keys      map[string]string // API key -> account ID
75		customers map[string]Customer
76		invoices  map[string]Invoice
77		seq       int
78	}
79	
80	// New returns an empty store.
81	func New() *Store {
82		return &Store{accounts: map[string]Account{}, keys: map[string]string{}, customers: map[string]Customer{}, invoices: map[string]Invoice{}}
83	}
84	
85	// AddAccount adds or replaces an account.
86	func (s *Store) AddAccount(a Account) {
87		s.mu.Lock()
88		defer s.mu.Unlock()
89		s.accounts[a.ID] = a
90	}
91	
92	// AddKey gives an account an API key.
93	func (s *Store) AddKey(key, accountID string) {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		s.keys[key] = accountID
97	}
98	
99	// AccountForKey returns the account an API key belongs to.
100	func (s *Store) AccountForKey(key string) (Account, bool) {
101		if key == "" {
102			return Account{}, false
103		}
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		id, ok := s.keys[key]
107		if !ok {
108			return Account{}, false
109		}
110		a, ok := s.accounts[id]
111		return a, ok
112	}
113	
114	func (s *Store) next(prefix string) string {
115		s.seq++
116		return fmt.Sprintf("%s_%05d", prefix, s.seq)
117	}
118	
119	// CreateCustomer adds a customer to an account.
120	func (s *Store) CreateCustomer(accountID, name, email string, plan Plan, now time.Time) (Customer, error) {
121		name, email = strings.TrimSpace(name), strings.TrimSpace(email)
122		if name == "" || !strings.Contains(email, "@") {
123			return Customer{}, fmt.Errorf("%w: a customer needs a name and an email address", ErrInvalid)
124		}
125		if plan == "" {
126			plan = PlanFree
127		}
128		if !plan.Valid() {
129			return Customer{}, fmt.Errorf("%w: unknown plan %q", ErrInvalid, plan)
130		}
131		s.mu.Lock()
132		defer s.mu.Unlock()
133		if _, ok := s.accounts[accountID]; !ok {
134			return Customer{}, ErrNotFound
135		}
136		c := Customer{ID: s.next("cus"), AccountID: accountID, Name: name, Email: email, Plan: plan, CreatedAt: now}
137		s.customers[c.ID] = c
138		return c, nil
139	}
140	
141	// Customer returns one of an account's customers.
142	func (s *Store) Customer(accountID, id string) (Customer, bool) {
143		s.mu.Lock()
144		defer s.mu.Unlock()
145		c, ok := s.customers[id]
146		if !ok || c.AccountID != accountID {
147			return Customer{}, false
148		}
149		return c, true
150	}
151	
152	// Customers returns an account's customers sorted by ID.
153	func (s *Store) Customers(accountID string) []Customer {
154		s.mu.Lock()
155		defer s.mu.Unlock()
156		out := []Customer{}
157		for _, c := range s.customers {
158			if c.AccountID == accountID {
159				out = append(out, c)
160			}
161		}
162		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
163		return out
164	}
165	
166	// CreateInvoice stores an invoice for one of the account's customers, with the account's tax rate.
167	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
168		if len(inv.Lines) == 0 {
169			return Invoice{}, fmt.Errorf("%w: an invoice needs at least one line", ErrInvalid)
170		}
171		for _, l := range inv.Lines {
172			if l.Quantity <= 0 || l.UnitCents < 0 {
173				return Invoice{}, fmt.Errorf("%w: a line needs a positive quantity and a price that is not negative", ErrInvalid)
174			}
175		}
176		if inv.CouponPercent < 0 || inv.CouponPercent > 100 || inv.CreditCents < 0 {
177			return Invoice{}, fmt.Errorf("%w: the coupon is 0 to 100 percent and the credit is not negative", ErrInvalid)
178		}
179		s.mu.Lock()
180		defer s.mu.Unlock()
181		a, ok := s.accounts[inv.AccountID]
182		if !ok {
183			return Invoice{}, ErrNotFound
184		}
185		if c, ok := s.customers[inv.CustomerID]; !ok || c.AccountID != inv.AccountID {
186			return Invoice{}, ErrNotFound
187		}
188		inv.ID = s.next("inv")
189		inv.TaxRateBP = a.TaxRateBP
190		inv.CreatedAt = now
191		inv.Lines = append([]LineItem(nil), inv.Lines...)
192		s.invoices[inv.ID] = inv
193		return inv, nil
194	}
195	
196	// Invoice returns one of an account's invoices.
197	func (s *Store) Invoice(accountID, id string) (Invoice, bool) {
198		s.mu.Lock()
199		defer s.mu.Unlock()
200		inv, ok := s.invoices[id]
201		if !ok || inv.AccountID != accountID {
202			return Invoice{}, false
203		}
204		return inv, true
205	}
206	
207	// Invoices returns an account's invoices, oldest first (ties by ID).
208	func (s *Store) Invoices(accountID string) []Invoice {
209		s.mu.Lock()
210		defer s.mu.Unlock()
211		out := []Invoice{}
212		for _, inv := range s.invoices {
213			if inv.AccountID == accountID {
214				out = append(out, inv)
215			}
216		}
217		sort.Slice(out, func(i, j int) bool {
218			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
219				return out[i].CreatedAt.Before(out[j].CreatedAt)
220			}
221			return out[i].ID < out[j].ID
222		})
223		return out
224	}
225

