67	func (s *Server) createCustomer(w http.ResponseWriter, r *http.Request, acct store.Account) {
68		var in struct {
69			Name  string     `json:"name"`
70			Email string     `json:"email"`
71			Plan  store.Plan `json:"plan"`
72		}
73		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
74			writeError(w, http.StatusBadRequest, "invalid_json")
75			return
76		}
77		c, err := s.store.CreateCustomer(acct.ID, in.Name, in.Email, in.Plan, s.now())
