// addInvoices creates n invoices for Acme; the i-th is made at at(i).
func addInvoices(t *testing.T, st *store.Store, n int, at func(i int) time.Time) {
	t.Helper()
	c, err := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < n; i++ {
		inv := store.Invoice{AccountID: "acc_acme", CustomerID: c.ID, Lines: []store.LineItem{{Description: "Seat", Quantity: 1, UnitCents: 100}}}
		if _, err := st.CreateInvoice(inv, at(i)); err != nil {
			t.Fatal(err)
		}
	}
}

type invoicePage struct {
	Items []struct {
		ID string `json:"id"`
	} `json:"items"`
	NextCursor string `json:"next_cursor"`
}

// listPage requests one page of Acme's invoices with the given query string.
func listPage(t *testing.T, h http.Handler, query string) invoicePage {
	t.Helper()
	r := do(t, h, "GET", "/api/invoices"+query, "key-acme", "")
	if r.Code != http.StatusOK {
		t.Fatalf("list %q: %d %s", query, r.Code, r.Body)
	}
	var p invoicePage
	if err := json.Unmarshal(r.Body.Bytes(), &p); err != nil {
		t.Fatal(err)
	}
	return p
}

// walkInvoices follows next_cursor from the first page of the given size and returns every invoice ID in order.
// between runs after each page that has a next page.
func walkInvoices(t *testing.T, h http.Handler, limit int, between func(page int)) []string {
	t.Helper()
	var ids []string
	cursor := ""
	for page := 1; ; page++ {
		if page > 1000 {
			t.Fatal("pagination never ends")
		}
		query := "?limit=" + strconv.Itoa(limit)
		if cursor != "" {
			query += "&cursor=" + cursor
		}
		p := listPage(t, h, query)
		for _, it := range p.Items {
			ids = append(ids, it.ID)
		}
		if p.NextCursor == "" {
			return ids
		}
		if len(p.Items) != limit {
			t.Fatalf("page %d has %d items with a next cursor, want %d", page, len(p.Items), limit)
		}
		cursor = p.NextCursor
		if between != nil {
			between(page)
		}
	}
}

func invoiceIDs(t *testing.T, st *store.Store) []string {
	t.Helper()
	var ids []string
	for _, inv := range st.Invoices("acc_acme") {
		ids = append(ids, inv.ID)
	}
	return ids
}

func TestInvoicesArePagedOldestFirst(t *testing.T) {
	srv, st := newServer(t)
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	addInvoices(t, st, 25, func(i int) time.Time { return base.Add(time.Duration(i) * time.Minute) })

	first := listPage(t, srv, "")
	if len(first.Items) != 20 || first.NextCursor == "" {
		t.Fatalf("default page: %d items, next %q; want 20 items and a next cursor", len(first.Items), first.NextCursor)
	}
	last := listPage(t, srv, "?limit=20&cursor="+first.NextCursor)
	if len(last.Items) != 5 || last.NextCursor != "" {
		t.Fatalf("last page: %d items, next %q; want 5 items and no next cursor", len(last.Items), last.NextCursor)
	}

	want := invoiceIDs(t, st)
	for _, limit := range []int{1, 7, 25, 100} {
		got := walkInvoices(t, srv, limit, nil)
		if strings.Join(got, ",") != strings.Join(want, ",") {
			t.Fatalf("limit %d: got %v, want %v", limit, got, want)
		}
	}
}

func TestInvoicesAtTheSameTimeArePagedByID(t *testing.T) {
	srv, st := newServer(t)
	at := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	addInvoices(t, st, 12, func(int) time.Time { return at })

	got := walkInvoices(t, srv, 5, nil)
	if len(got) != 12 {
		t.Fatalf("got %d invoices, want 12: %v", len(got), got)
	}
	for i := 1; i < len(got); i++ {
		if got[i-1] >= got[i] {
			t.Fatalf("not in ID order: %v", got)
		}
	}
}

func TestInvoiceLimitIsAWholeNumberFromOneToOneHundred(t *testing.T) {
